<script setup lang="ts">
import type { DocumentRecord, Page } from '~/utils/types'
const api=useApi();const docs=ref<DocumentRecord[]>([]);const cursor=ref<string|null>();const error=ref<unknown>();const loading=ref(false)
async function load(more=false){loading.value=true;error.value=undefined;try{const page=await api.get<Page<DocumentRecord>>(`/documents?scope=origin&limit=50${more&&cursor.value?`&cursor=${encodeURIComponent(cursor.value)}`:''}`);docs.value=more?[...docs.value,...page.items]:page.items;cursor.value=page.next_cursor}catch(e){error.value=e}finally{loading.value=false}}
onMounted(()=>load())
</script>
<template><div class="page-head"><div><h1>หนังสือของหน่วยงาน</h1><p>ทะเบียนเฉพาะหนังสือที่หน่วยงานของคุณเป็นต้นทาง แยกจากงานประจำ Station</p></div><NuxtLink class="button primary" to="/documents/new">ลงทะเบียนหนังสือ</NuxtLink></div><Feedback :error="error" /><section class="panel"><div class="page-head"><h2>ทะเบียนหนังสือ</h2><button type="button" class="text-link" @click="load()">โหลดล่าสุด</button></div><UProgress v-if="loading" /><div v-if="!docs.length&&!loading" class="empty"><h3>ยังไม่มีหนังสือของหน่วยงาน</h3><p>เลือกเส้นทางและลงทะเบียนหนังสือเพื่อเริ่มติดตาม</p></div><div class="table-wrap"><table v-if="docs.length"><thead><tr><th>หนังสือ</th><th>รูปแบบ</th><th>สถานะงาน</th><th>Workflow</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.id"><td><NuxtLink :to="`/documents/${doc.id}`">{{doc.title||doc.document_number}}</NuxtLink><p v-if="doc.title&&doc.document_number" class="hint">{{doc.document_number}}</p></td><td>Model {{doc.tracking_mode}}</td><td><StatusTag :value="doc.business_state" /></td><td><StatusTag :value="doc.process_sync_status" /></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดหนังสือเพิ่มเติม</button></section></template>
